public record MekanismDamageType(ResourceKey<DamageType> key, float exhaustion, DamageEffects effects) implements IHasTranslationKey {

    public DamageType toVanilla() {
        return new DamageType(registryName().toLanguageKey(), exhaustion, effects);
    }

    public Identifier registryName() {
        return key.identifier();
    }

    @Override
    public String getTranslationKey() {
        return registryName().toLanguageKey("death.attack");
    }

    public boolean is(DamageSource source) {
        return source.is(key);
    }

    public DamageSource source(Level level) {
        return source(level.registryAccess());
    }

    public DamageSource source(RegistryAccess registryAccess) {
        return new DamageSource(holder(registryAccess));
    }

    public DamageSource source(Level level, Vec3 position) {
        return source(level.registryAccess(), position);
    }

    public DamageSource source(RegistryAccess registryAccess, Vec3 position) {
        return new DamageSource(holder(registryAccess), position);
    }

    public DamageSource source(RegistryAccess registryAccess, @Nullable Entity directEntity, @Nullable Entity causingEntity) {
        return new DamageSource(holder(registryAccess), directEntity, causingEntity);
    }

    private Holder<DamageType> holder(RegistryAccess registryAccess) {
        return registryAccess.holderOrThrow(key());
    }
}

package mekanism.api.lasers;

/// Expose as a capability on armor items to allow lasers to be dissipated and/or refracted through entities wearing your armor.
///
/// @implNote The order in which things are checked for reducing damage is as follows:
///
///   1. Shield an entity is blocking with
///   2. Total dissipation percent of worn armor
///   3. Total refraction percent of worn armor
///
/// Any damage that isn't blocked, dissipated, or refracted through the entity will be applied to the entity as normal.
public interface ILaserDissipation {

    /// Gets the percentage for how much of a laser's energy this piece of armor will dissipate across it.
    ///
    /// @return Laser dissipation percentage (0.0 to 1.0F).
    ///
    /// @implNote This value should be between zero and one, but values greater than one will work as well as the total percentage across the worn armor gets capped at
    /// one.
    float getDissipationPercent();

    /// Gets the percentage for how much of a laser's energy this piece of armor will be refracted through it.
    ///
    /// @return Laser refraction percentage (0.0 to 1.0F).
    ///
    /// @implNote This value should be between zero and one, but values greater than one will work as well as the total percentage across the worn armor gets capped at
    /// one.
    float getRefractionPercent();
}

